-- AM PAYMENTS_CHECKOUT: seis remediaciones V3; no modifica fuentes vigentes ni publica.
-- Fuentes: reglas legadas 208/523/540, 209/524/525, 212/533/534,
-- 276/288/521, 185, 539/316. Consolidaciones solo propuestas (JSON de evidencia).
-- Los hechos creados son logicos, no bindings runtime. Juicio CONTEXTO_ACTUAL.
BEGIN;
DO $pre$
DECLARE n integer;
BEGIN
 SELECT count(*) INTO n FROM lf_ops.nucleo_reglas WHERE familia='PAYMENTS_CHECKOUT' AND estado='CANDIDATA';
 IF n<>10
 OR (SELECT count(*) FROM lf_ops.reglas)<1
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones v JOIN lf_ops.nucleo_reglas r ON r.codigo=v.regla WHERE r.familia='PAYMENTS_CHECKOUT' AND v.version=2 AND v.estado='CANDIDATA')<>8
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones v JOIN lf_ops.nucleo_reglas r ON r.codigo=v.regla WHERE r.familia='PAYMENTS_CHECKOUT' AND v.version=1 AND v.estado='DESCARTADA')<>8
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones v JOIN lf_ops.nucleo_reglas r ON r.codigo=v.regla WHERE r.familia='PAYMENTS_CHECKOUT' AND v.version>=3)<>0
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones v JOIN lf_ops.nucleo_reglas r ON r.codigo=v.regla WHERE r.familia='PAYMENTS_CHECKOUT' AND v.estado='PUBLICADA')<>0
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla IN('REG_CHK_002','REG_TEC_007') AND version=2 AND estado='CANDIDATA')<>2
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla IN('REG_CHK_006','REG_CHK_007') AND version=1 AND estado='CANDIDATA')<>2
 OR EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo='REG_CHK_CUO_003')
 THEN RAISE EXCEPTION 'AM_V3_BASE_DRIFT candidates=%',n; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.nucleo_hechos WHERE codigo IN('quote_misma_operacion_vigente','estado_carta_normalizado','integracion_aliado_carta_auto_habilitada','consentimiento_debito_evidencia_vinculada','reserva_idempotente_corresponde_request','evidencia_qr_corresponde_misma_operacion'))
 THEN RAISE EXCEPTION 'AM_V3_FACT_COLLISION'; END IF;
END $pre$;

INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion) VALUES
('quote_misma_operacion_vigente','boolean','ninguna','Hecho lógico sin binding runtime: backend coteja user_id, quote_status VALID, expires_at y selección de lf_proto.checkout_pricing_quotes con intento reservado.'),
('estado_carta_normalizado','text','ninguna','Hecho lógico sin binding runtime: estado documental por deuda definido por REG_CLIENT_NO_DEBT_LETTER_STATUS_001; registry backend aún PENDING.'),
('integracion_aliado_carta_auto_habilitada','boolean','ninguna','Hecho lógico sin binding runtime: capacidad contractual e integración real del aliado para solicitar carta automáticamente (regla vigente 534).'),
('consentimiento_debito_evidencia_vinculada','boolean','ninguna','Hecho lógico sin binding runtime: evidencia de timestamp, medio y versión de cronograma aceptado exigida por regla 521.'),
('reserva_idempotente_corresponde_request','boolean','ninguna','Hecho lógico sin binding runtime: match de user_id/idempotency_key/request_sha256/operation_number en public.lf_checkout_idempotency_reservations.'),
('evidencia_qr_corresponde_misma_operacion','boolean','ninguna','Hecho lógico sin binding runtime: referencia de evidencia autoritativa QR coincide con operación reservada; 539 exige conservar referencia.');
INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen)
SELECT 'PAYMENTS_CHECKOUT',unnest(ARRAY['quote_misma_operacion_vigente','estado_carta_normalizado','integracion_aliado_carta_auto_habilitada','consentimiento_debito_evidencia_vinculada','reserva_idempotente_corresponde_request','evidencia_qr_corresponde_misma_operacion']),'CURADO';

DO $am$
DECLARE item jsonb; p jsonb; judge jsonb; proposal jsonb; dry jsonb; replay jsonb;
 v2 record; old_eval jsonb; new_eval jsonb; old_snapshot jsonb; old_tests jsonb; old_judges jsonb;
 old_legacy_md5 text; code text; h2 text; h3 text; rv integer:=0; old_count integer;
BEGIN
 SELECT count(*),md5(string_agg(to_jsonb(r)::text,'|' ORDER BY id))
 INTO old_count,old_legacy_md5 FROM lf_ops.reglas r;
 FOR item IN SELECT value FROM jsonb_array_elements($v3$[{"codigo":"REG_CHK_004","version_anterior":2,"nota_anterior":70,"hash_v2":"621f8002b3d92689015e2b637ecbbb21a7b48004950da6cd213fe5196f600969","motivo_revision":"Agregar cotejo de quote y operación real al reintento seguro, sin afirmar binding runtime del backend.","patch":{"titulo":"Bloqueo de reintento no reconciliado, no autorizado o con quote inválido","descripcion":"Un intento de checkout ya iniciado mantiene bloqueado el reintento mientras no exista un outcome normalizado seguro, permiso explícito del backend o validez de la misma reserva de operación y quote original. El backend debe comprobar user_id, quote_status=VALID, expires_at y referencia reservada antes de emitir los hechos. Un timeout ambiguo nunca autoriza segundo cobro. Antes del primer envío esta regla no bloquea el inicio.","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"intento_pago_iniciado"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"y","izq":{"op":"!=","izq":{"hecho":"estado_pago_normalizado"},"der":{"lit":"PAYMENT_DECLINED_CONFIRMED"}},"der":{"op":"y","izq":{"op":"!=","izq":{"hecho":"estado_pago_normalizado"},"der":{"lit":"PAYMENT_NOT_SUBMITTED"}},"der":{"op":"!=","izq":{"hecho":"estado_pago_normalizado"},"der":{"lit":"PAYMENT_PROVIDER_UNAVAILABLE_BEFORE_SUBMIT"}}}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"reintento_autorizado_backend"},"der":{"lit":false}},"der":{"op":"=","izq":{"hecho":"quote_misma_operacion_vigente"},"der":{"lit":false}}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"intento_pago_iniciado":true,"estado_pago_normalizado":"PAYMENT_PENDING_CONFIRMATION","reintento_autorizado_backend":false,"quote_misma_operacion_vigente":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"intento_pago_iniciado":true,"estado_pago_normalizado":"PAYMENT_CONFIRMED","reintento_autorizado_backend":true,"quote_misma_operacion_vigente":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"intento_pago_iniciado":true,"estado_pago_normalizado":"PAYMENT_DECLINED_CONFIRMED","reintento_autorizado_backend":true,"quote_misma_operacion_vigente":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"intento_pago_iniciado":true,"estado_pago_normalizado":"PAYMENT_NOT_SUBMITTED","reintento_autorizado_backend":false,"quote_misma_operacion_vigente":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"intento_pago_iniciado":true,"estado_pago_normalizado":"PAYMENT_DECLINED_CONFIRMED","reintento_autorizado_backend":true,"quote_misma_operacion_vigente":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"intento_pago_iniciado":true,"estado_pago_normalizado":"PAYMENT_NOT_SUBMITTED","reintento_autorizado_backend":true,"quote_misma_operacion_vigente":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"intento_pago_iniciado":true,"estado_pago_normalizado":"PAYMENT_PROVIDER_UNAVAILABLE_BEFORE_SUBMIT","reintento_autorizado_backend":true,"quote_misma_operacion_vigente":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"intento_pago_iniciado":false,"estado_pago_normalizado":"SIN_INTENTO","reintento_autorizado_backend":false,"quote_misma_operacion_vigente":false},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica AM V3 (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"208: bloquear CTA para impedir doble submit."},"CAL_ALCANCE":{"puntaje":1,"observacion":"CLIENT_PAYMENTS evita aplicar a home, onboarding o legal."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Texto identifica bloqueo y resultados que habilitan reintento."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR coincide con bloqueo de CTA."},"COH_TEXTO_CONDICION":{"puntaje":1,"observacion":"Condición incluye primer intento, outcome seguro, permiso backend y quote de la misma operación vigente; comprobación funcional hecha con negativos, binding runtime aún pendiente."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"Restringe reintento a misma operación y quote respaldado; no contradice normalización de 523 ni handoff 540. Falta demostrar señal backend real."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Comparte estados con 523/540, pero se limita al bloqueo CTA de reintento; consolidación de fuentes no realizada."}}},"riesgos":["intento_pago_iniciado","reintento_autorizado_backend","estado_pago_normalizado","quote_misma_operacion_vigente","join quote-reserva/operación real, reconciliación y decisión server-side"]},{"codigo":"REG_CHK_005","version_anterior":2,"nota_anterior":75,"hash_v2":"df05be0a06e55226b8cf6582d2ad5e941576fca6bb0dfa85746040cfb58728fe","motivo_revision":"Convertir permiso amplio en guard de bloqueo explícito de render; proponer consolidación con regla vigente de éxito 525, sin ejecutarla.","patch":{"titulo":"Bloquear pantalla de éxito si faltan confirmación o datos autoritativos","descripcion":"En CHECKOUT_PAGO_EXITOSO bloquear el render como pago exitoso cuando el backend aún no ha confirmado PAYMENT_CONFIRMED o no verificó referencia, fecha y monto real. No genera acciones de post-pago, no cambia onboarding_completed ni emite carta: esas operaciones permanecen sujetas a las reglas backend vigentes. Es la condición negativa de seguridad para la pantalla y se propone integrarla después con REG_CLIENT_PAYMENT_SUCCESS_VIEW_001; no sustituye esa regla.","efecto":"BLOQUEAR","condicion":{"op":"o","izq":{"op":"!=","izq":{"hecho":"estado_pago_normalizado"},"der":{"lit":"PAYMENT_CONFIRMED"}},"der":{"op":"=","izq":{"hecho":"datos_pago_backend_verificados"},"der":{"lit":false}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_PENDING_CONFIRMATION","datos_pago_backend_verificados":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_DECLINED_CONFIRMED","datos_pago_backend_verificados":true},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_CONFIRMED","datos_pago_backend_verificados":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_pago_normalizado":"PAYMENT_CONFIRMED","datos_pago_backend_verificados":true},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica AM V3 (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"209/524: permite acciones solo tras confirmación."},"CAL_ALCANCE":{"puntaje":1,"observacion":"PANTALLA-33 es CHECKOUT_PAGO_EXITOSO verificada en árbol de alcance; deja backend por deuda fuera de esta vista."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Define pantalla de éxito, outcome y datos del backend sin prometer activación del plan."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR representa el guard negativo de render, separado de contenido de éxito."},"COH_TEXTO_CONDICION":{"puntaje":1,"observacion":"Se bloquea si no hay PAYMENT_CONFIRMED o falta verificación backend, con caso de rechazo y confirmado sin datos."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"No muta onboarding ni emite carta; 524 y reglas de plan quedan con el backend."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Sigue solapado con REG_CLIENT_PAYMENT_SUCCESS_VIEW_001 (525); se documenta propuesta de consolidación, sin ejecución ni retiro."}}},"riesgos":["estado_pago_normalizado desde ledger/proveedor","datos_pago_backend_verificados: referencia, fecha, monto confirmados","guard real de CHECKOUT_PAGO_EXITOSO"]},{"codigo":"REG_CHK_008","version_anterior":2,"nota_anterior":72,"hash_v2":"e8485ea9c6db5d442f70fc5c0d4dd483f2cd3b6a63d0bb676c3c3a75effc1e6d","motivo_revision":"Corregir supuesto de solicitud manual: backend inicia automáticamente por deuda cuando el aliado tiene integración, sin fusionar regla 534.","patch":{"titulo":"Inicio automático de trámite de Carta solo por deuda liquidada y aliado habilitado","descripcion":"En BACKEND y para cada deuda, permitir iniciar automáticamente la solicitud o generación de Carta de No Adeudo solo cuando el ledger establece SETTLED_CONFIRMED, el estado documental es ELIGIBLE y la integración vigente del aliado permite el inicio automático. El frontend no exige una solicitud manual ni equipara pago inicial a liquidación, emisión o descarga. El ciclo NOT_ELIGIBLE a AVAILABLE y la descarga siguen gobernados por REG_CLIENT_NO_DEBT_LETTER_STATUS_001; la consolidación con esa regla se propone sin ejecutarse.","clase":"BACKEND","alcance":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"estado_liquidacion_deuda"},"der":{"lit":"SETTLED_CONFIRMED"}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"estado_carta_normalizado"},"der":{"lit":"ELIGIBLE"}},"der":{"op":"=","izq":{"hecho":"integracion_aliado_carta_auto_habilitada"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"estado_liquidacion_deuda":"SETTLED_CONFIRMED","estado_carta_normalizado":"ELIGIBLE","integracion_aliado_carta_auto_habilitada":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_liquidacion_deuda":"PLAN_ACTIVO","estado_carta_normalizado":"NOT_ELIGIBLE","integracion_aliado_carta_auto_habilitada":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_liquidacion_deuda":"SETTLED_CONFIRMED","estado_carta_normalizado":"PROCESSING","integracion_aliado_carta_auto_habilitada":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_liquidacion_deuda":"SETTLED_CONFIRMED","estado_carta_normalizado":"ELIGIBLE","integracion_aliado_carta_auto_habilitada":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"estado_liquidacion_deuda":"PAYMENT_PENDING_CONFIRMATION","estado_carta_normalizado":"ELIGIBLE","integracion_aliado_carta_auto_habilitada":true},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica AM V3 (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"212/280/292/327: diferir solicitud hasta liquidación total."},"CAL_ALCANCE":{"puntaje":1,"observacion":"BACKEND más condición por deuda ajusta flujo de solicitud automática, sin CTA manual en CLIENT_PAYMENTS."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"El requisito de SETTLED_CONFIRMED es explícito."},"COH_EFECTO":{"puntaje":1,"observacion":"PERMITIR solicitud cuando la deuda está liquidada coincide con elegibilidad."},"COH_TEXTO_CONDICION":{"puntaje":1,"observacion":"Liquidación SETTLED_CONFIRMED, ELIGIBLE y capacidad de integración del aliado hacen explícitas tres precondiciones de auto solicitud."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"Coherente con no emitir carta por pago inicial y con estados del documento regulados aparte."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"El ciclo documental y la auto solicitud ya constan en 534; consolidación propuesta, sin editar fuente vigente."}}},"riesgos":["estado_liquidacion_deuda por deuda (ledger canónico pendiente)","estado_carta_normalizado por deuda (registro documental pendiente)","integracion_aliado_carta_auto_habilitada verificada contrato/adapter"]},{"codigo":"REG_CHK_013","version_anterior":2,"nota_anterior":75,"hash_v2":"fc83ad384693305504857f1264e49c4ee2964ecdeae9b514a9c9760a91156c75","motivo_revision":"Incorporar evidencia vinculada de consentimiento; mantener autoridad de regla vigente 521 hasta consolidación aprobada.","patch":{"titulo":"Bloquear cuotas automáticas sin consentimiento y evidencia vinculada","descripcion":"En CHECKOUT_CUOTAS_MEDIO_PAGO, cuando el backend determina que el medio elegido requiere débito recurrente automático, bloquear hasta que exista autorización explícita y evidencia verificable de timestamp, contexto del medio y versión del cronograma o condiciones aceptadas. No bloquear cuotas con cobro futuro manual ni pago único por este consentimiento. El contrato vigente REG_CLIENT_CHECKOUT_AUTODEBIT_CONSENT_CONTEXT_001 conserva la autoridad; la consolidación es solo propuesta.","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"modalidad_pago"},"der":{"lit":"CUOTAS"}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"debito_automatico_requerido"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"autoriza_debito_automatico"},"der":{"lit":false}},"der":{"op":"=","izq":{"hecho":"consentimiento_debito_evidencia_vinculada"},"der":{"lit":false}}}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"modalidad_pago":"CUOTAS","debito_automatico_requerido":true,"autoriza_debito_automatico":false,"consentimiento_debito_evidencia_vinculada":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"modalidad_pago":"CUOTAS","debito_automatico_requerido":true,"autoriza_debito_automatico":true,"consentimiento_debito_evidencia_vinculada":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"modalidad_pago":"CUOTAS","debito_automatico_requerido":true,"autoriza_debito_automatico":true,"consentimiento_debito_evidencia_vinculada":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"modalidad_pago":"CUOTAS","debito_automatico_requerido":false,"autoriza_debito_automatico":false,"consentimiento_debito_evidencia_vinculada":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"modalidad_pago":"PAGO_UNICO","debito_automatico_requerido":false,"autoriza_debito_automatico":false,"consentimiento_debito_evidencia_vinculada":false},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica AM V3 (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"276/288: bloquear CTA sin consentimiento."},"CAL_ALCANCE":{"puntaje":1,"observacion":"PANTALLA-21 corresponde a CHECKOUT_CUOTAS_MEDIO_PAGO; no hereda a otros flujos."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"El texto comunica el requisito, aunque lo generaliza."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR cuando falta autorización coincide con el texto histórico."},"COH_TEXTO_CONDICION":{"puntaje":1,"observacion":"Además de requerir débito recurrente, bloquea si falta evidencia vinculada a cronograma/medio aun con checkbox marcado."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"Respeta no exigir autorización en cuotas manuales y la prueba exige evidencia antes de iniciar automático."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"REG_CLIENT_CHECKOUT_AUTODEBIT_CONSENT_CONTEXT_001 (521) gobierna exactamente el consentimiento; consolidación no ejecutada."}}},"riesgos":["debito_automatico_requerido del flag backend RECURRING_AUTODEBIT_AUTH_REQUIRED","autoriza_debito_automatico firmado y registrado","consentimiento_debito_evidencia_vinculada con timestamp/version cronograma/medio"]},{"codigo":"REG_TEC_009","version_anterior":2,"nota_anterior":75,"hash_v2":"5bbd755219c88a504d831943f8ee224ff2ab96e853a8ae2cd50f436c2340a70b","motivo_revision":"Amarrar reutilización al usuario, hash de request y operation_number existentes; sin afirmar resultado original recuperable ni resolver borde no acreditado.","patch":{"titulo":"Respuesta idempotente reutilizable solo para reserva y petición equivalentes","descripcion":"En checkout, una clave previamente registrada solo permite recuperar la misma respuesta de operación si coincide usuario, idempotency_key y request_sha256, existe operation_number asociado y la antigüedad es estrictamente menor que AUTH/IDEMPOTENCY_KEY_VALIDITY_MINUTES. En el borde exacto no se abre una segunda operación: se requiere reconciliación aparte, criterio técnico conservador no validado aún contra runtime. La respuesta original se devuelve sin repetir cargo ni rechazar indiscriminadamente la misma petición. Los campos existen en public.lf_checkout_idempotency_reservations, pero el binding y la recuperación real del resultado no están acreditados.","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"operacion_es_checkout"},"der":{"lit":true}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"clave_idempotencia_repetida"},"der":{"lit":true}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"peticion_idempotente_equivalente"},"der":{"lit":true}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"reserva_idempotente_corresponde_request"},"der":{"lit":true}},"der":{"op":"<","izq":{"hecho":"edad_clave_idempotencia"},"der":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES"}}}}}},"pruebas":[{"casuistica":"BAJO_EL_LIMITE","entrada":{"operacion_es_checkout":true,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":true,"reserva_idempotente_corresponde_request":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":-1}},"esperado":true},{"casuistica":"EN_EL_LIMITE","entrada":{"operacion_es_checkout":true,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":true,"reserva_idempotente_corresponde_request":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES"}},"esperado":false},{"casuistica":"SOBRE_EL_LIMITE","entrada":{"operacion_es_checkout":true,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":true,"reserva_idempotente_corresponde_request":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":1}},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"operacion_es_checkout":true,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":false,"reserva_idempotente_corresponde_request":false,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":-1}},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"operacion_es_checkout":true,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":true,"reserva_idempotente_corresponde_request":false,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":-1}},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"operacion_es_checkout":false,"clave_idempotencia_repetida":true,"peticion_idempotente_equivalente":true,"reserva_idempotente_corresponde_request":true,"edad_clave_idempotencia":{"param":"AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","mas":-1}},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica AM V3 (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"185: devolver resultado anterior sin duplicados."},"CAL_ALCANCE":{"puntaje":1,"observacion":"operacion_es_checkout limita la regla a checkout aunque el nodo técnico sea BACKEND."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Describe reenvío con clave y ventana configurada."},"COH_EFECTO":{"puntaje":1,"observacion":"PERMITIR describe reutilizar la respuesta anterior, no generar otra operación, frente al antiguo RECHAZAR."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"Comprueba reserva asociada a usuario/request_sha256/operation_number y el límite parametrizado; el borde exacto y la recuperación de resultado aún necesitan prueba runtime."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"No reprocesa ni rechaza indiscriminadamente una petición equivalente; condición restringe resultado al mismo intento."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"Comparte idempotencia con fuentes B2B/ONB; no se afirma integración ni sustitución de la legada 185."}}},"riesgos":["reserva_idempotente_corresponde_request desde verificación transaccional","edad_clave_idempotencia desde reloj server y AUTH.IDEMPOTENCY_KEY_VALIDITY_MINUTES","retorno del resultado persistido sin ejecutar nuevo cargo","semántica del borde exacto de ventana y retención del resultado"]},{"codigo":"REG_CLIENT_CHECKOUT_QR_CONFIRMATION_001","version_anterior":2,"nota_anterior":75,"hash_v2":"55bf33b5895be2ef9791dcc4e08fc092515b5030376aef903b57b0dd1734a002","motivo_revision":"Validar que evidencia QR corresponde a la misma operación y preservar confirmaciones tardías sin permitir otro cargo.","patch":{"titulo":"Bloquear confirmación QR sin evidencia de la misma operación","descripcion":"En la pantalla CHECKOUT_ESTADO_YAPE_QR, bloquear el avance a PAYMENT_CONFIRMED si falta evidencia autoritativa de pago o si la evidencia no corresponde a la misma referencia de operación QR reservada. El CTA Ya escaneé solo solicita al backend consulta o reconciliación de esa referencia, nunca crea otra operación ni certifica éxito por clic. La expiración gobierna reutilizar el QR para un nuevo pago, no revoca por sí misma una confirmación genuina tardía; la reconciliación y expiración permanecen bajo la regla vigente 539.","condicion":{"op":"o","izq":{"op":"=","izq":{"hecho":"evidencia_autoritativa_pago"},"der":{"lit":false}},"der":{"op":"=","izq":{"hecho":"evidencia_qr_corresponde_misma_operacion"},"der":{"lit":false}}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"evidencia_autoritativa_pago":false,"evidencia_qr_corresponde_misma_operacion":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"evidencia_autoritativa_pago":true,"evidencia_qr_corresponde_misma_operacion":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"evidencia_autoritativa_pago":true,"evidencia_qr_corresponde_misma_operacion":true},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"evidencia_autoritativa_pago":false,"evidencia_qr_corresponde_misma_operacion":true},"esperado":true}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 revisión semántica AM V3 (contexto actual, no independiente)","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"539/316: verificar mismo QR sin inventar confirmación."},"CAL_ALCANCE":{"puntaje":1,"observacion":"PANTALLA-28 corresponde exactamente a CHECKOUT_ESTADO_YAPE_QR."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"El texto distingue consulta y confirmación de pago."},"COH_EFECTO":{"puntaje":1,"observacion":"BLOQUEAR se limita a confirmar como pagado sin evidencia, no impide consultar estado mediante el CTA."},"COH_TEXTO_CONDICION":{"puntaje":1,"observacion":"Combina evidencia autoritativa y pertenencia a la misma operación; una confirmación tardía legítima no queda invalidada solo por expirar el QR."},"SEM_NO_CONTRADICE":{"puntaje":1,"observacion":"Respeta reconciliación backend y no habilita un nuevo pago desde CTA manual."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"La norma vigente 539 conserva la consulta, expiración y estados; solo se modela guard, sin consolidar ni retirar."}}},"riesgos":["evidencia_autoritativa_pago del proveedor canónico","evidencia_qr_corresponde_misma_operacion ligada a referencia reservada","vencimiento QR sin impedir confirmación tardía","conector/ledger y conciliador de callbacks verificable"]}]$v3$::jsonb) LOOP
  code:=item->>'codigo';
  SELECT * INTO v2 FROM lf_ops.nucleo_regla_versiones WHERE regla=code AND version=2 AND estado='CANDIDATA';
  IF v2.version IS NULL OR v2.hash IS DISTINCT FROM item->>'hash_v2'
   OR (SELECT count(*) FROM lf_ops.nucleo_juicios j WHERE j.regla=code AND j.version=2)<>1
  THEN RAISE EXCEPTION 'AM_V3_EXPECTED_V2_MISSING_OR_HASH_DRIFT %',code; END IF;
  old_snapshot:=to_jsonb(v2);
  SELECT jsonb_agg(to_jsonb(t) ORDER BY n) INTO old_tests FROM lf_ops.nucleo_regla_pruebas t WHERE regla=code AND version=2;
  SELECT jsonb_agg(to_jsonb(jj) ORDER BY id) INTO old_judges FROM lf_ops.nucleo_juicios jj WHERE regla=code AND version=2;
  old_eval:=lf_ops.nucleo_regla_evaluar_v1(code,false);
  IF old_eval->>'decision'<>'DEVUELTA' OR (old_eval->>'nota')::integer IS DISTINCT FROM (item->>'nota_anterior')::integer
  THEN RAISE EXCEPTION 'AM_V3_V2_EVALUATION_DRIFT % %',code,old_eval; END IF;
  SELECT jsonb_agg(jsonb_build_object('casuistica',casuistica,'entrada',entrada,'esperado',esperado) ORDER BY n)
  INTO p FROM lf_ops.nucleo_regla_pruebas WHERE regla=code AND version=2;
  proposal:=v2.ficha || jsonb_build_object('pruebas',p) || (item->'patch') ||
    jsonb_build_object('tipo','REVISION','version_anterior',2,'hash_anterior',v2.hash,
                       'motivo_revision',item->>'motivo_revision');
  IF proposal->'origen' IS DISTINCT FROM v2.origen
   OR proposal->>'autoridad' IS DISTINCT FROM v2.autoridad
   OR proposal->>'codigo' IS DISTINCT FROM code
  THEN RAISE EXCEPTION 'AM_V3_ORIGIN_AUTHORITY_DRIFT %',code; END IF;
  dry:=lf_ops.nucleo_regla_proponer_v1(proposal,false);
  IF dry->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (dry->>'bloqueantes')::integer<>0
  THEN RAISE EXCEPTION 'AM_V3_PREFLIGHT_REJECTED % %',code,dry; END IF;
  p:=lf_ops.nucleo_regla_proponer_v1(proposal,true);
  IF p->>'resultado'<>'CANDIDATA' OR (p->>'version')::integer<>3
  THEN RAISE EXCEPTION 'AM_V3_DOOR_FAILED % %',code,p; END IF;
  IF (SELECT to_jsonb(v)-'estado' FROM lf_ops.nucleo_regla_versiones v WHERE regla=code AND version=2)
       IS DISTINCT FROM old_snapshot-'estado'
  OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY n) FROM lf_ops.nucleo_regla_pruebas t WHERE regla=code AND version=2)
       IS DISTINCT FROM old_tests
  OR (SELECT jsonb_agg(to_jsonb(jj) ORDER BY id) FROM lf_ops.nucleo_juicios jj WHERE regla=code AND version=2)
       IS DISTINCT FROM old_judges
  OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=code AND version=2)<>'DESCARTADA'
  OR (SELECT estado FROM lf_ops.nucleo_regla_versiones WHERE regla=code AND version=3)<>'CANDIDATA'
  THEN RAISE EXCEPTION 'AM_V3_HISTORY_MUTATED %',code; END IF;
  IF (SELECT jsonb_agg(jsonb_build_object('casuistica',casuistica,'entrada',entrada,'esperado',esperado) ORDER BY n)
     FROM lf_ops.nucleo_regla_pruebas WHERE regla=code AND version=3) IS DISTINCT FROM proposal->'pruebas'
  THEN RAISE EXCEPTION 'AM_V3_TESTS_NOT_COPIED %',code; END IF;
  IF (SELECT ficha->>'motivo_revision' FROM lf_ops.nucleo_regla_versiones WHERE regla=code AND version=3)
   IS DISTINCT FROM item->>'motivo_revision'
  THEN RAISE EXCEPTION 'AM_V3_REASON_NOT_PERSISTED %',code; END IF;
  h3:=lf_ops.nucleo_hash_paquete_v1(code,3);
  IF h3 IS NULL OR h3=lf_ops.nucleo_hash_paquete_v1(code,2)
  THEN RAISE EXCEPTION 'AM_V3_PACKAGE_HASH_COLLISION %',code; END IF;
  judge:=item->'juicio'||jsonb_build_object('regla',code,'hash_evaluado',h3,
   'evidencia_ref','https://github.com/cristhianlujan/claude-persona-lf-patch/blob/main/sandbox/lf_contract_gate_test/nucleo_ci/checkout_am_revisiones_v3.json#'||code);
  -- Expected negative: invalid hash must fail the hash guard, not another control.
  BEGIN
   PERFORM lf_ops.nucleo_juicio_registrar_v1(judge||jsonb_build_object('hash_evaluado',repeat('0',64)));
   RAISE EXCEPTION 'AM_V3_BAD_JUDGE_HASH_ACCEPTED %',code;
  EXCEPTION WHEN others THEN
   IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF;
  END;
  PERFORM lf_ops.nucleo_juicio_registrar_v1(judge);
  new_eval:=lf_ops.nucleo_regla_evaluar_v1(code,true);
  IF new_eval->>'decision'<>'DEVUELTA' OR judge->>'veredicto'<>'DEVOLVER'
  THEN RAISE EXCEPTION 'AM_V3_FALSE_AUTO % %',code,new_eval; END IF;
  -- Expected negative: cannot publish a returned candidate without approval.
  BEGIN
   PERFORM lf_ops.nucleo_version_publicar_v1(code,3);
   RAISE EXCEPTION 'AM_V3_UNSAFE_PUBLICATION %',code;
  EXCEPTION WHEN others THEN
   IF SQLERRM NOT LIKE 'NUCLEO_PUBLICAR_SIN_PROMOCION:%' THEN RAISE; END IF;
  END;
  replay:=lf_ops.nucleo_regla_proponer_v1(proposal,false);
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(replay->'controles') x WHERE
    x->>'n'='0' AND x->>'detalle'='REVISION_VERSION_OBSOLETA' AND (x->>'ok')::boolean=false)
  THEN RAISE EXCEPTION 'AM_V3_REPLAY_NOT_REJECTED % %',code,replay; END IF;
  RAISE NOTICE 'AM_V3_RESULT %',jsonb_build_object('codigo',code,'v2_nota',old_eval->'nota',
   'v3_nota',new_eval->'nota','v3_decision',new_eval->>'decision',
   'hash_v3',h3,'veredicto',judge->>'veredicto','motivos',new_eval->'motivos',
   'componente_calidad',new_eval->'componentes'->'calidad',
   'componente_semantica',new_eval->'componentes'->'semantica',
   'motivo_revision',item->>'motivo_revision');
  rv:=rv+1;
 END LOOP;
 IF rv<>6
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones v JOIN lf_ops.nucleo_reglas n ON n.codigo=v.regla
     WHERE n.familia='PAYMENTS_CHECKOUT' AND v.version=3 AND v.estado='CANDIDATA')<>6
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones v JOIN lf_ops.nucleo_reglas n ON n.codigo=v.regla
     WHERE n.familia='PAYMENTS_CHECKOUT' AND v.version=2 AND v.estado='DESCARTADA')<>6
 OR (SELECT count(*) FROM lf_ops.nucleo_juicios WHERE version=3 AND regla IN(
    'REG_CHK_004','REG_CHK_005','REG_CHK_008','REG_CHK_013','REG_TEC_009','REG_CLIENT_CHECKOUT_QR_CONFIRMATION_001'))<>6
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla IN('REG_CHK_002','REG_TEC_007')
     AND version=2 AND estado='CANDIDATA')<>2
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE regla IN('REG_CHK_006','REG_CHK_007')
     AND version=1 AND estado='CANDIDATA')<>2
 OR EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo='REG_CHK_CUO_003')
 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones v JOIN lf_ops.nucleo_reglas n ON n.codigo=v.regla
     WHERE n.familia='PAYMENTS_CHECKOUT' AND v.estado='PUBLICADA')<>0
 OR (SELECT count(*) FROM lf_ops.reglas)<>old_count
 OR (SELECT md5(string_agg(to_jsonb(r)::text,'|' ORDER BY id)) FROM lf_ops.reglas r) IS DISTINCT FROM old_legacy_md5
 OR EXISTS(SELECT * FROM lf_ops.reglas EXCEPT ALL SELECT * FROM lf_ops.v_reglas_compat_v1 WHERE id IS NOT NULL)
 OR EXISTS(SELECT * FROM lf_ops.v_reglas_compat_v1 WHERE id IS NOT NULL EXCEPT ALL SELECT * FROM lf_ops.reglas)
 THEN RAISE EXCEPTION 'AM_V3_FINAL_READBACK_FAILED'; END IF;
 RAISE NOTICE 'AM_V3_PASS 6/6 candidatas V3, 6/6 juicios, 0 publicadas, 0 reglas vigentes editadas, % legadas intactas',old_count;
END $am$;
COMMIT;
